styleText:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --bg:         #F7F7F4;
      --white:      #FFFFFF;
      --accent:     #CDB18B;
      --accent-dim: #F2E4CF;
      --dark:       #0D1117;
      --dark-2:     #1A1F2E;
      --dark-3:     #0F1520;
      --text:       #111111;
      --muted:      #6B7280;
      --muted-2:    #9CA3AF;
      --border:     rgba(0,0,0,0.07);
      --border-2:   rgba(0,0,0,0.12);
      --shadow-xs:  0 1px 3px rgba(0,0,0,0.05);
      --shadow-sm:  0 2px 10px rgba(0,0,0,0.06);
      --shadow-md:  0 8px 32px rgba(0,0,0,0.08);
      --shadow-lg:  0 20px 60px rgba(0,0,0,0.10);
      --shadow-xl:  0 40px 100px rgba(0,0,0,0.12);
      --radius-sm:  10px;
      --radius-md:  16px;
      --radius-lg:  24px;
      --radius-xl:  32px;
      --radius-full:9999px;
    }
    html { scroll-behavior: smooth; }
    body { font-family: 'Inter', sans-serif; background: var(--bg); color: var(--text); line-height: 1.6; overflow-x: hidden; -webkit-font-smoothing: antialiased; }
    a { text-decoration: none; color: inherit; }

    @keyframes fadeInUp { from { opacity:0; transform:translateY(24px);} to { opacity:1; transform:translateY(0);} }
    @keyframes pulse-dot { 0%,100%{opacity:1;transform:scale(1);} 50%{opacity:.5;transform:scale(.85);} }
    .fade-in-up { animation: fadeInUp 0.7s cubic-bezier(.22,1,.36,1) both; }
    .d1{animation-delay:.1s;} .d2{animation-delay:.2s;} .d3{animation-delay:.3s;} .d4{animation-delay:.4s;}

    .container { width:100%; max-width:1200px; margin:0 auto; padding:0 32px; }
    .section { padding:100px 0; }
    .eyebrow { display:inline-flex;align-items:center;gap:7px;font-size:11px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin-bottom:18px; }
    .eyebrow-dot { width:6px;height:6px;border-radius:50%;background:var(--accent);animation:pulse-dot 2s ease infinite; }
    .section-headline { font-size:clamp(30px,4vw,46px);font-weight:800;line-height:1.1;letter-spacing:-.025em;margin-bottom:14px; }
    .section-sub { font-size:16px;color:var(--muted);max-width:520px;line-height:1.7; }

    /* Buttons */
    .btn { display:inline-flex;align-items:center;gap:8px;border-radius:var(--radius-full);font-family:'Inter',sans-serif;font-weight:600;font-size:14px;cursor:pointer;transition:all .2s cubic-bezier(.22,1,.36,1);border:none;white-space:nowrap; }
    .btn-primary { background:var(--dark);color:#fff;padding:13px 28px;box-shadow:0 2px 8px rgba(0,0,0,.15); }
    .btn-primary:hover { background:var(--dark-2);transform:translateY(-2px);box-shadow:0 8px 24px rgba(0,0,0,.2); }
    .btn-accent  { background:var(--accent);color:var(--dark);padding:13px 28px;box-shadow:0 2px 8px rgba(205,177,139,.3); }
    .btn-accent:hover { background:#dac09e;transform:translateY(-2px);box-shadow:0 8px 24px rgba(205,177,139,.4); }
    .btn-outline { background:transparent;color:var(--text);padding:12px 24px;border:1.5px solid var(--border-2); }
    .btn-outline:hover { background:var(--white);color:#0D1117 !important;transform:translateY(-1px);box-shadow:var(--shadow-sm); }
    .btn-outline-light { background:transparent;color:rgba(255,255,255,.75);padding:12px 24px;border:1.5px solid rgba(255,255,255,.2); }
    .btn-outline-light:hover { background:rgba(255,255,255,.08); }
    .btn-full { width:100%;justify-content:center; }

    /* ── Navbar ── */
    .navbar { position:fixed;top:0;left:0;right:0;z-index:1000;padding:0 40px;height:64px;display:flex;align-items:center;justify-content:space-between;background:rgba(247,247,244,.82);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-bottom:1px solid var(--border); }
    .nav-logo { display:flex;align-items:center;gap:9px;font-weight:800;font-size:18px;letter-spacing:-.03em; }
    .nav-logo-icon { width:30px;height:30px;background:var(--dark);border-radius:8px;display:flex;align-items:center;justify-content:center; }
    .nav-logo-icon svg { width:16px;height:16px; }
    .nav-links { display:flex;align-items:center;gap:2px;list-style:none; }
    .nav-links a { font-size:13px;font-weight:500;color:var(--muted);padding:7px 11px;border-radius:var(--radius-full);transition:all .15s;display:flex;align-items:center;gap:3px; }
    .nav-links a:hover,.nav-links a.active { color:var(--text);background:rgba(0,0,0,.04); }
    .nav-links a.active { color:var(--text);font-weight:600;background:rgba(0,0,0,.06); }
    .nav-actions { display:flex;align-items:center;gap:10px; }
    .nav-chevron { font-size:9px;opacity:.45; }
    .nav-item { position:relative;list-style:none; }
    .nav-item.has-mega:hover .nav-chevron,
    .nav-item.has-mega.mega-open .nav-chevron { transform:rotate(180deg);opacity:.7; }
    .mega-panel { position:fixed;top:64px;left:50%;transform:translateX(-50%) translateY(-6px);background:var(--white);border:1px solid var(--border-2);border-radius:var(--radius-lg);box-shadow:0 8px 16px rgba(0,0,0,.06),0 24px 64px rgba(0,0,0,.10);padding:24px;opacity:0;pointer-events:none;transition:opacity .18s ease,transform .18s ease;z-index:999; }
    .nav-item.has-mega:hover .mega-panel,
    .nav-item.has-mega.mega-open .mega-panel {
      opacity: 1;
      pointer-events: auto;
      transform: translateX(-50%) translateY(0);
    }
    .mega-products  { width:1040px; }
    .mega-solutions { width:680px; }
    .mega-platform  { width:680px; }
    /* Thin top accent bar */
    .mega-panel::before { content:'';position:absolute;top:0;left:24px;right:24px;height:2px;background:var(--accent);border-radius:0 0 2px 2px;opacity:.6; }
    /* Transparent hover bridge — prevents gap closing the menu */
    .mega-panel::after {
      content: '';
      position: absolute;
      top: -18px; left: 0; right: 0;
      height: 18px;
    }

    /* Hightouch-style column mega */
    .mega-cols { display:flex; align-items:flex-start; gap:0; }
    .mega-col {
      flex:1; padding:0 28px;
      border-right:1px solid var(--border-2);
      min-width:0;
    }
    .mega-col:first-child { padding-left:0; }
    .mega-col:last-child  { border-right:none; }

    .mega-col-label {
      font-size:10px; font-weight:700; letter-spacing:.1em;
      text-transform:uppercase; color:var(--muted);
      margin-bottom:16px; padding-bottom:12px;
      border-bottom:1px solid var(--border-2);
      white-space:nowrap;
    }
    .mega-col-link {
      display:block; font-size:14px; color:var(--text);
      text-decoration:none; padding:7px 0; font-weight:500;
      transition:color .15s; white-space:nowrap;
    }
    .mega-col-link:hover { color:var(--accent); }

    .mega-col-badge {
      font-size:9px; font-weight:700; letter-spacing:.05em;
      text-transform:uppercase; color:var(--accent);
      background:rgba(205,177,139,.15); border-radius:3px;
      padding:2px 5px; margin-left:6px; vertical-align:middle;
    }

    /* Featured column */
    .mega-col-featured { flex:0 0 200px !important; padding:0 0 0 28px !important; border-right:none !important; }
    .mega-featured-img {
      width:100%; height:110px; border-radius:var(--radius-sm);
      overflow:hidden; margin-bottom:12px;
    }
    .mega-featured-img img { width:100%; height:100%; object-fit:cover; }
    .mega-featured-desc {
      font-size:12.5px; color:var(--muted); line-height:1.65; margin-bottom:12px;
    }
    .mega-featured-link {
      font-size:12.5px; font-weight:600; color:var(--text);
      text-decoration:none; display:flex; align-items:center; gap:4px;
    }
    .mega-featured-link:hover { color:var(--accent); }

    /* ── Hero ── */
    .pricing-hero {
      background:var(--bg);
      padding:100px 0 120px;
      text-align:center;
      position:relative;
      overflow:hidden;
    }
    .pricing-hero-bg {
      position:absolute;top:0;left:0;right:0;z-index:0;
      width:100%;height:auto;object-fit:unset;
      pointer-events:none;
    }
    .pricing-hero .container { position:relative;z-index:1; }
    .pricing-hero::before { display:none; }
    .pricing-hero h1 {
      font-size:clamp(36px,5vw,64px);font-weight:900;line-height:1.04;letter-spacing:-.04em;
      color:var(--text);margin-bottom:20px;
    }
    .pricing-hero h1 em { font-style:italic;font-family:'DM Serif Display',serif;font-weight:400;color:var(--text); } h2 em { font-style:italic; font-family:'DM Serif Display',serif; font-weight:400; } .section-headline em { font-style:italic; font-family:'DM Serif Display',serif; font-weight:400; }
    .pricing-hero p { font-size:18px;color:var(--muted);max-width:500px;margin:0 auto 48px;line-height:1.75; }
    .pricing-hero .eyebrow { color:var(--muted); }
    .pricing-hero .plans-heading { margin-top:80px;margin-bottom:0; }
    .pricing-hero .plans-heading h2 { font-size:clamp(28px,3.5vw,42px);font-weight:800;color:var(--text);letter-spacing:-.03em;margin-bottom:10px; }
    .pricing-hero .plans-heading p  { font-size:15px;color:var(--muted);max-width:500px;margin:0 auto; }

    /* Billing toggle */
    .billing-toggle {
      display:inline-flex;align-items:center;gap:0;
      background:rgba(0,0,0,.06);border:1px solid rgba(0,0,0,.1);
      border-radius:var(--radius-full);padding:4px;
    }
    .billing-btn {
      padding:8px 22px;border-radius:var(--radius-full);font-size:13px;font-weight:600;
      cursor:pointer;transition:all .2s;border:none;background:transparent;color:var(--muted);
    }
    .billing-btn.active { background:var(--dark);color:#fff; }
    .billing-save {
      display:inline-flex;align-items:center;
      font-size:11px;font-weight:700;color:#8A6B40;
      background:var(--accent-dim);border:1px solid rgba(205,177,139,.4);
      padding:3px 10px;border-radius:var(--radius-full);margin-left:12px;
    }

    /* ── Platform Pricing Cards ── */
    .plans-grid {
      display:grid;grid-template-columns:repeat(3,1fr);gap:24px;
      align-items:stretch;margin-top:48px;
    }
    .plan-card {
      background:var(--white);
      border-radius:28px;
      box-shadow:none;
      overflow:hidden;
      transition:transform .25s cubic-bezier(.22,1,.36,1);
      border:none;
      display:flex;flex-direction:column;
    }
    .plan-card:hover { transform:translateY(-5px); }

    /* Inner header panel */
    .plan-header {
      margin:12px 12px 0;
      border-radius:20px;
      padding:24px 24px 20px;
      background:var(--bg);
      position:relative;
      display:flex;flex-direction:column;align-items:flex-start;
    }
    .plan-card.featured .plan-header {
      background:linear-gradient(140deg, #CDB18B 0%, #e8d0aa 55%, #f0dfc0 100%);
    }
    .plan-card.enterprise .plan-header {
      background:#EBEBEB;
    }

    /* Pill badge */
    .plan-badge-pill {
      display:inline-block;
      background:rgba(255,255,255,.92);
      color:var(--text);
      font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;
      padding:5px 14px;border-radius:var(--radius-full);
      margin-bottom:22px;
      box-shadow:0 1px 4px rgba(0,0,0,.08);
    }

    /* Price inside header */
    .plan-price {
      display:flex;align-items:baseline;gap:1px;
    }
    .plan-currency { font-size:28px;font-weight:800;color:var(--text);line-height:1; }
    .plan-amount   { font-size:52px;font-weight:900;letter-spacing:-.04em;color:var(--text);line-height:1; }
    .plan-per      { font-size:15px;font-weight:500;color:var(--muted);margin-left:3px;align-self:flex-end;padding-bottom:6px; }

    /* Body */
    .plan-body { padding:20px 28px 28px;flex:1;display:flex;flex-direction:column; }
    .plan-desc { font-size:14px;color:var(--muted);line-height:1.65;margin-bottom:20px;text-align:left; }
    .plan-divider { height:1px;background:var(--border);margin-bottom:20px; }
    .plan-features { list-style:none;display:flex;flex-direction:column;gap:11px;margin-top:20px;flex:1; }
    .plan-feature  { display:flex;align-items:flex-start;gap:10px;font-size:13.5px;color:var(--text); }
    .plan-check { width:18px;height:18px;border-radius:50%;background:var(--accent-dim);color:var(--accent);display:flex;align-items:center;justify-content:center;font-size:10px;flex-shrink:0;margin-top:2px;font-weight:800; }
    .plan-x     { width:18px;height:18px;border-radius:50%;background:rgba(0,0,0,.05);color:var(--muted-2);display:flex;align-items:center;justify-content:center;font-size:10px;flex-shrink:0;margin-top:2px; }

    /* ── App-based Pricing ── */
    .apps-grid {
      display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:48px;
    }
    .app-price-card {
      background:var(--white);border:1px solid var(--border-2);border-radius:var(--radius-lg);
      padding:24px;transition:all .2s;position:relative;overflow:hidden;
    }
    .app-price-card:hover { border-color:var(--accent);box-shadow:var(--shadow-md);transform:translateY(-2px); }
    .app-price-card.dark-app { background:var(--dark);border-color:transparent; }
    .app-price-icon { font-size:26px;margin-bottom:12px;display:block; }
    .app-price-name { font-size:16px;font-weight:800;letter-spacing:-.02em;color:var(--text);margin-bottom:4px;display:flex;align-items:center;gap:8px;flex-wrap:wrap; }
    .app-price-card.dark-app .app-price-name { color:#fff; }
    .app-price-cat { font-size:10px;font-weight:600;color:var(--muted);letter-spacing:.06em;text-transform:uppercase;margin-bottom:16px; }
    .app-price-card.dark-app .app-price-cat { color:rgba(255,255,255,.35); }
    .app-price-amount { font-size:28px;font-weight:900;letter-spacing:-.03em;color:var(--text);line-height:1; }
    .app-price-card.dark-app .app-price-amount { color:#fff; }
    .app-price-unit { font-size:12px;color:var(--muted);margin-top:3px; }
    .app-price-card.dark-app .app-price-unit { color:rgba(255,255,255,.4); }
    .app-price-soon { opacity:.6; }

    /* ── Comparison Table ── */
    .compare-table {
      width:100%;border-collapse:collapse;margin-top:48px;
    }
    .compare-table th { padding:16px 20px;text-align:left;font-size:12px;font-weight:700;color:var(--muted);letter-spacing:.06em;text-transform:uppercase;border-bottom:2px solid var(--border-2); }
    .compare-table th.plan-col { text-align:center;width:160px; }
    .compare-table th.plan-col.featured-col { color:var(--accent); }
    .compare-table td { padding:16px 20px;font-size:14px;color:var(--text);border-bottom:1px solid var(--border); }
    .compare-table td.plan-col { text-align:center;width:160px; }
    .compare-table tr:last-child td { border-bottom:none; }
    .compare-table .section-row td { background:var(--bg);font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);padding:12px 20px; }
    .compare-table tr:hover td { background:rgba(0,0,0,.015); }
    .compare-table .section-row:hover td { background:var(--bg); }
    .check-icon { width:22px;height:22px;border-radius:50%;background:var(--accent-dim);color:var(--accent);display:inline-flex;align-items:center;justify-content:center;font-size:11px;font-weight:800; }
    .x-icon { width:22px;height:22px;border-radius:50%;background:rgba(0,0,0,.05);color:var(--muted-2);display:inline-flex;align-items:center;justify-content:center;font-size:11px; }
    .featured-col-bg { background:rgba(205,177,139,.04); }

    /* ── FAQ Accordion ── */
    .faq-header-row {
      display:flex;align-items:flex-start;justify-content:space-between;
      gap:40px;margin-bottom:48px;
    }
    .faq-header-left { max-width:700px; }
    .faq-header-left .faq-badge {
      display:inline-block;font-size:11px;font-weight:600;color:var(--muted);
      background:var(--bg);border:1px solid var(--border-2);
      padding:4px 12px;border-radius:var(--radius-full);letter-spacing:.06em;
      text-transform:uppercase;margin-bottom:16px;
    }
    .faq-header-left h2 {
      font-size:clamp(26px,3vw,38px);font-weight:800;letter-spacing:-.03em;
      color:var(--text);line-height:1.15;margin-bottom:12px;
    }
    .faq-header-left p { font-size:14px;color:var(--muted);line-height:1.7;white-space:nowrap; }
    .faq-view-all {
      flex-shrink:0;padding:10px 22px;border-radius:var(--radius-full);
      font-size:13px;font-weight:600;color:var(--text);
      border:1.5px solid var(--border-2);background:var(--white);
      cursor:pointer;transition:all .2s;white-space:nowrap;
    }
    .faq-view-all:hover { background:var(--bg);border-color:rgba(0,0,0,.15); }

    .faq-cols { display:grid;grid-template-columns:1fr 1fr;gap:0 48px; }
    .faq-item {
      border-bottom:1px solid var(--border-2);overflow:hidden;
    }
    .faq-item:first-child { border-top:1px solid var(--border-2); }
    .faq-q {
      display:flex;align-items:center;justify-content:space-between;gap:16px;
      padding:18px 0;cursor:pointer;
      font-size:14px;font-weight:600;color:var(--text);letter-spacing:-.01em;
      user-select:none;
    }
    .faq-icon {
      width:26px;height:26px;border-radius:50%;background:var(--bg);
      border:1.5px solid var(--border-2);
      display:flex;align-items:center;justify-content:center;
      flex-shrink:0;font-size:14px;font-weight:400;color:var(--muted);
      transition:all .2s;line-height:1;
    }
    .faq-item.open .faq-icon { background:var(--dark);border-color:var(--dark);color:#fff; }
    .faq-a {
      font-size:13.5px;color:var(--muted);line-height:1.75;
      max-height:0;overflow:hidden;
      transition:max-height .3s ease,padding .3s ease;
      padding:0;
    }
    .faq-item.open .faq-a { max-height:160px;padding-bottom:18px; }

    /* ── Footer ── */
    .footer {
      background:var(--dark);color:rgba(255,255,255,.6);
      position:relative;overflow:hidden;
      padding-top:0;
    }
    .footer-bg { position:absolute;inset:0;z-index:0;opacity:.35; }
    .footer-bg img { width:100%;height:100%;object-fit:cover; }
    .footer > .container { position:relative;z-index:1; }
    .footer-grid { display:grid;grid-template-columns:2fr 1fr 1fr 1fr 1fr;gap:48px;padding-bottom:48px; }
    .footer-brand p { font-size:13px;color:rgba(255,255,255,.4);line-height:1.7;margin-top:14px;max-width:220px; }
    .footer-brand .nav-logo { color:#fff; }
    .footer-col-title { font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:rgba(255,255,255,.3);margin-bottom:16px; }
    .footer-col ul { list-style:none;display:flex;flex-direction:column;gap:10px; }
    .footer-col a { font-size:13px;color:rgba(255,255,255,.5);transition:color .15s; }
    .footer-col a:hover { color:#fff; }
    .footer-bottom { border-top:1px solid rgba(255,255,255,.07);padding:24px 0;display:flex;align-items:center;justify-content:space-between; }
    .footer-bottom-text { font-size:12px;color:rgba(255,255,255,.25); }
    .footer-socials { display:flex;gap:8px; }
    .footer-social { width:32px;height:32px;border-radius:8px;background:rgba(255,255,255,.06);display:flex;align-items:center;justify-content:center;font-size:12px;cursor:pointer;transition:background .15s; }
    .footer-social:hover { background:rgba(255,255,255,.12); }

    @media(max-width:1024px) { .plans-grid { grid-template-columns:1fr 1fr; } .plan-card.featured { transform:none; } .apps-grid { grid-template-columns:repeat(3,1fr); } .compare-table { font-size:13px; } }
    @media(max-width:768px) { .navbar { padding:0 20px; } .nav-links { display:none; } .container { padding:0 20px; } .section { padding:72px 0; } .plans-grid { grid-template-columns:1fr; } .apps-grid { grid-template-columns:1fr 1fr; } .faq-grid { grid-template-columns:1fr; } .footer-grid { grid-template-columns:1fr; } }

/* ─── WATERCOLOR REVEAL ─── */
#wc-overlay {
  position: fixed;
  inset: 0;
  z-index: 99999;
  pointer-events: none;
}
#wc-canvas {
  display: block;
  width: 100%;
  height: 100%;
  filter: url(#wc-ink);
}

    /* ─── TESTIMONIALS ─── */
    .testimonials-section { background: var(--bg); overflow: hidden; position: relative; padding-bottom:0 !important; }
    .testimonials-section .testi-bg { position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center top;z-index:0; }
    .testimonials-section .container,
    .testimonials-section .testi-v2-cols { position:relative;z-index:1; }
    .testi-v2-header { display:flex;flex-direction:column;align-items:center;text-align:center;max-width:540px;margin:0 auto 56px; }
    .testi-v2-h2 { font-size:clamp(30px,4vw,46px);font-weight:800;letter-spacing:-.025em;line-height:1.1;color:var(--text);margin-bottom:14px;white-space:nowrap; }
    .testi-v2-cols { display:flex;justify-content:center;gap:20px;max-height:580px;overflow:hidden;padding:0 24px;-webkit-mask-image:linear-gradient(to bottom,transparent,black 12%,black 100%);mask-image:linear-gradient(to bottom,transparent,black 12%,black 100%); }
