    .mobile-nav-links a:hover { background: rgba(0,0,0,0.05); } .mobile-nav-sub { list-style: none; padding: 4px 0 4px 12px; display: flex; flex-direction: column; gap: 0; } .mobile-nav-sub a { font-size: 13px !important; padding: 7px 12px !important; color: var(--muted) !important; font-weight: 500 !important; border-radius: 8px; } .mobile-nav-sub a:hover { color: var(--text) !important; background: rgba(0,0,0,0.04) !important; } .mobile-nav-sub a.active { color: var(--accent) !important; font-weight: 600 !important; background: rgba(205,177,139,0.12) !important; }
    .mobile-nav-cta { display: flex; align-items: center; justify-content: center; margin-top: 12px; width: 100%; text-align: center; }
    @media (max-width: 768px) { .nav-burger { display: flex; } .testi-v2-h2 { white-space: normal !important; } .nav-actions { display: flex !important; margin-left: auto; gap: 8px; } .nav-actions .btn-primary { padding: 8px 14px; font-size: 12px; white-space: nowrap; box-shadow: none; } .footer-grid { grid-template-columns: repeat(3, 1fr) !important; } .footer-brand { grid-column: 1 / -1; } .footer-brand p { max-width: 100%; } }
